CREATE TABLE questions(id INTEGER DEFAULT(nextval('questions_id_seq')) PRIMARY KEY, questions VARCHAR, surveys_id INTEGER NOT NULL, drivers_id INTEGER NOT NULL, qcode VARCHAR, FOREIGN KEY (surveys_id) REFERENCES surveys(id), FOREIGN KEY (drivers_id) REFERENCES drivers(id));;
INSERT INTO questions VALUES(1,'Your Department''s (i.e. Operations, Merchandising etc.) effectiveness',1,1,'bpb|effectiveness');
INSERT INTO questions VALUES(2,'The level of customer service (internal or external) your Team provides',1,1,'bpb|customer_service');
INSERT INTO questions VALUES(3,'Managing costs and resources in your Team',1,1,'bpb|change_cost_management');
INSERT INTO questions VALUES(4,'Increases in revenue',1,2,'sfa|revenue_growth');
INSERT INTO questions VALUES(5,'Reduced costs',1,2,'sfa|auto_benefits_reduced_costs');
INSERT INTO questions VALUES(6,'Improved customer shopping experience',1,2,'sfa|customer_experience');
INSERT INTO questions VALUES(7,'Better efficiency and productivity',1,2,'sfa|benefits_improved_efficiency');
INSERT INTO questions VALUES(8,'Greater team collaboration and communication',1,2,'sfa|benefits_collaboration');
INSERT INTO questions VALUES(9,'Better resource management',1,2,'sfa|auto_benefits_better_resource_use');
INSERT INTO questions VALUES(10,'How confident are you that the performance of your Department will improve because 7-Eleven''s transformation has been implemented?',1,2,'sfb|lv1_success');
INSERT INTO questions VALUES(11,'Your team''s effectiveness at getting work done',1,1,'bpb|effectiveness');
INSERT INTO questions VALUES(12,'The level of service your team provides to internal/external customers (e.g. HR serves employees (internal customers), Finance serves vendors (external customers), Researchers support scientific findings)',1,1,'bpb|customer_service');
INSERT INTO questions VALUES(13,'Managing costs and resources in your organisation / team',1,1,'bpb|change_cost_management');
INSERT INTO questions VALUES(14,'Team alignment between A*STAR and Research Entities on HR, FIN, Procurement and Scholarship processes',1,2,'sfa|increased_alignment_business');
INSERT INTO questions VALUES(15,'Time savings through simplified HR, Finance, procurement, scholarship and employee-related functionalities and processes',1,2,'sfa|auto_benefits_better_integration');
INSERT INTO questions VALUES(16,'Improved employee experience through a digital front door',1,2,'sfa|benefits_employee_exp');
INSERT INTO questions VALUES(17,'A scalable workforce with enhanced insights (e.g., spend, talent, supplier visibility) and data-driven decision-making capabilities',1,2,'sfa|auto_benefits_better_data-driven_decisions');
INSERT INTO questions VALUES(18,'How confident are you that the performance of your team will improve because ERP 2.0 has been implemented?',1,2,'sfb|lv1_success');
INSERT INTO questions VALUES(19,'How clear are your roles and responsibilities within your team?',2,3,'llb|role_clarity');
INSERT INTO questions VALUES(20,'How much are people in your team held accountable for achieving their objectives?',2,3,'llb|accountable');
INSERT INTO questions VALUES(21,'To what extent does your team have clear performance objectives and measurable outcomes?',2,3,'llb|objectives_outcomes');
INSERT INTO questions VALUES(22,'How would you rate the overall management capability of your direct supervisor in leading change implementation - building and mobilising people''s commitment?',2,4,'llb|leads_implementation');
INSERT INTO questions VALUES(23,'How would you rate the overall management capability of your direct supervisor in coaching people to develop their potential?',2,4,'llb|performance_management');
INSERT INTO questions VALUES(24,'To what degree do you feel your talents and capabilities are being fully utilised?',2,4,'llb|talents_utilised');
INSERT INTO questions VALUES(25,'How confident and trusting are you in your direct supervisor''s leadership?',2,4,'llb|conf_lv5_ldr');
INSERT INTO questions VALUES(26,'How recognised and rewarded do you feel for achieving results?',2,4,'llb|recognised_rewarded');
INSERT INTO questions VALUES(27,'To what extent has your Leadership (e.g., DCEs, Group Directors, RI Executive Directors) actively demonstrated support and commitment for ERP 2.0?',2,5,'enb|ldr_support_system');
INSERT INTO questions VALUES(28,'To what extent has your Leadership (e.g., DCEs, Group Directors, RI Executive Directors) provided the appropriate levels of time and resources needed to ensure ERP 2.0 is successful?',2,5,'enb|ldr_time_resources');
INSERT INTO questions VALUES(29,'How confident and trusting are you in your leadership?',2,5,'enb|conf_lv2_ldr');
INSERT INTO questions VALUES(30,'How well does your Leadership (e.g., DCEs, Group Directors, RI Executive Directors) lead ERP 2.0?',2,5,'sfb|current_change_mgmt');
INSERT INTO questions VALUES(31,'To what extent has your Leadership (e.g., DCEs, Group Directors, RI Executive Directors) addressed critical issues/problems related to ERP 2.0?',2,5,'rsb|quick_remedial');
INSERT INTO questions VALUES(32,'TGenerally, what are people feeling within your team (also taking into account your own feelings)?',2,6,'eeb|fear');
INSERT INTO questions VALUES(33,'Distress - e.g., people feel sad, hurting, helpless, in need',2,6,'eeb|distress');
INSERT INTO questions VALUES(34,'Anger - e.g., people feel cynical, angry, bored, blaming',2,6,'eeb|anger');
